mapper.select:
SELECT DISTINCT wcvd.id, wcvd.kb_id as kbId, wcvd.title, wcvd.severity, wcvd.release_date as releaseDate, wcvd.description, CASE WHEN wpn.id IS NOT NULL THEN 1 ELSE 0 END as status FROM win_cvb_db wcvd LEFT JOIN win_product_name wpn ON wcvd.kb_id = wpn.kb_id
AND wpn.host_id = #{hostId}
ORDER BY wcvd.release_date DESC
